    var first = found[0];
    var last = found[found.length - 1];
    arrangeLinePart(first.el, "greeting");
    used.push(first.el);
    if (last.el === first.el) return [{ el: first.el, key: "greeting" }];
    arrangeLinePart(last.el, "signOff");
    used.push(last.el);
    return [{ el: first.el, key: "greeting" }, { el: last.el, key: "signOff" }];
