    window.addEventListener("resize", onResize);
    // 多标签同步：配置只在打开页面时读过一次，另一个标签页改了文案/阈值这边看不到。
    // 回到本标签页（或重新聚焦）时补读一次，比常驻轮询省电。
    var lastLoad = 0;
